use ibapi::prelude::*;
use time::macros::datetime;
use tracing::{info, error};
use anyhow::Result;

#[tokio::main]
async fn main() -> Result<()> {
    // Initialize tracing
    tracing_subscriber::fmt::init();

    info!("Starting Interactive Brokers Trading App");

    // TODO: Move to configuration
    let connection_url = "127.0.0.1:7500"; // Correct TWS port

    info!("Connecting to TWS at {}", connection_url);

    let client = match Client::connect(connection_url, 100).await {
        Ok(client) => {
            info!("Successfully connected to TWS");
            client
        }
        Err(e) => {
            error!("Failed to connect to TWS: {}", e);
            return Err(anyhow::anyhow!("Connection to TWS failed: {}", e));
        }
    };

    // Example: Get historical data for AAPL
    let contract = Contract::stock("AAPL");

    info!("Requesting historical data for AAPL");

    let historical_data = client
        .historical_data(
            &contract,
            Some(datetime!(2023-04-11 20:00 UTC)),
            1.days(),
            BarSize::Hour,
            WhatToShow::Trades,
            true,
        )
        .await?;

    info!("Historical data received - start: {:?}, end: {:?}", 
        historical_data.start, historical_data.end);

    for bar in &historical_data.bars {
        info!("Bar: {:?}", bar);
    }

    info!("Application completed successfully");

    Ok(())
}

