use dotenv::dotenv;
use serde::{Deserialize, Serialize};
use std::env;
use anyhow::{Result, Context};
use tracing::info;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppConfig {
    pub tws: TwsConfig,
    pub trading: TradingConfig,
    pub ui: UiConfig,
    pub logging: LoggingConfig,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TwsConfig {
    pub host: String,
